'use strict';

/**
* Minimum half-precision floating-point number.
*
* @module @stdlib/constants/float16/min
* @type {number}
*
* @example
* var FLOAT16_MIN = require( '@stdlib/constants/float16/min' );
* // returns 6.103515625e-05
*/


// MAIN //

/**
* The minimum half-precision floating-point number.
*
* ## Notes
*
* The minimum is given by
*
* ```tex
* 2^{-14}
* ```
*
* @constant
* @type {number}
* @default 6.103515625e-05
* @see [half-precision floating-point form]{@link https://en.wikipedia.org/wiki/Half-precision_floating-point_format}
*/
var FLOAT16_MIN = 6.103515625e-05;


// EXPORTS //

module.exports = FLOAT16_MIN;
